import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  isLoggedIn = false;

  constructor(private router: Router) {}

  ngOnInit() {
    this.checkLogin();
    // Simplified login check for demo
    window.addEventListener('storage', () => this.checkLogin());
  }

  checkLogin() {
    this.isLoggedIn = !!localStorage.getItem('token');
  }

  logout() {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    this.isLoggedIn = false;
    this.router.navigate(['/login']);
  }
}
<nav class="navbar glass-card">
  <div class="container flex justify-between items-center">
    <div class="logo">
      <span class="logo-text">Bairro <span class="highlight">Seguro</span></span>
    </div>
    <div class="nav-links flex gap-4">
      <a routerLink="/" class="nav-link">Home</a>
      <a *ngIf="!isLoggedIn" routerLink="/login" class="nav-link">Login</a>
      <a *ngIf="!isLoggedIn" routerLink="/register" class="nav-link">Cadastrar</a>
      <a *ngIf="isLoggedIn" routerLink="/report" class="nav-link">Relatar Incidente</a>
      <a *ngIf="isLoggedIn" routerLink="/profile" class="nav-link">Meu Perfil</a>
      <a *ngIf="isLoggedIn" (click)="logout()" class="nav-link cursor-pointer">Sair</a>
    </div>
  </div>
</nav>

<main class="container mt-8 animate-fade-in">
  <router-outlet></router-outlet>
</main>

<style>
.navbar {
  margin: 1rem;
  padding: 1rem 0;
  position: sticky;
  top: 1rem;
  z-index: 1000;
}
.logo-text {
  font-size: 1.5rem;
  font-weight: 800;
}
.highlight {
  color: var(--primary);
}
.nav-link {
  color: var(--text-main);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.3s ease;
}
.nav-link:hover {
  color: var(--primary);
}
.cursor-pointer {
  cursor: pointer;
}
</style>
